const r = $input.first().json;

const money = (n) => 'Rs ' + Number(n || 0).toLocaleString('en-PK', { minimumFractionDigits: 0, maximumFractionDigits: 0 });

const cogs = Number(r.costOfGoodsSold || 0);
const revenue = Number(r.revenue || 0);
const grossProfit = revenue - cogs;
const marginPct = revenue ? Math.round((grossProfit / revenue) * 1000) / 10 : 0;
const avgOrder = r.salesCount ? Math.round(revenue / r.salesCount) : 0;

// ---- top items with medal ranks ----
const medals = ['🥇', '🥈', '🥉'];
const topRows = (r.topItems || []).length
  ? r.topItems.map((t, i) => `<tr style="background:${i % 2 === 0 ? '#fdf6ee' : '#ffffff'};">
      <td style="padding:11px 14px;border-bottom:1px solid #f0e0d0;font-weight:600;">${i < 3 ? medals[i] : (i + 1) + '.'} ${t.name}</td>
      <td style="padding:11px 14px;border-bottom:1px solid #f0e0d0;text-align:center;">${t.qty}</td>
      <td style="padding:11px 14px;border-bottom:1px solid #f0e0d0;text-align:right;">${money(t.revenue)}</td>
      <td style="padding:11px 14px;border-bottom:1px solid #f0e0d0;text-align:right;color:#15803d;font-weight:700;">${money(t.profit)}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:14px;color:#999;text-align:center;">No sales today.</td></tr>';

const badgeList = (items, color, bg, emptyText) => {
  if (!items || !items.length) return `<div style="color:#999;font-size:13px;">${emptyText}</div>`;
  return '<div>' + items.map(x => `<span style="display:inline-block;background:${bg};color:${color};padding:5px 12px;border-radius:14px;font-size:12px;margin:3px 4px 3px 0;font-weight:600;">${x}</span>`).join('') + '</div>';
};

const lowItems = (r.lowStockItems || []).map(i => `${i.name} (${i.stock} left)`);
const outItems = r.outOfStockItems || [];

// ---- bar-chart style breakdown ----
const bars = (rows, colors) => {
  const maxval = Math.max(...rows.map(x => x[1] || 0), 1);
  return rows.map(([label, val, icon], i) => {
    const pctOfMax = maxval ? Math.round(((val || 0) / maxval) * 100) : 0;
    const pctOfRev = revenue ? Math.round(((val || 0) / revenue) * 1000) / 10 : 0;
    return `<div style="margin-bottom:12px;">
      <div style="display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:4px;">
        <span>${icon} ${label}</span>
        <span style="font-weight:700;">${money(val)} <span style="color:#999;font-weight:400;">(${pctOfRev}%)</span></span>
      </div>
      <div style="background:#f1ede8;border-radius:6px;height:8px;overflow:hidden;">
        <div style="background:${colors[i]};width:${pctOfMax}%;height:100%;border-radius:6px;"></div>
      </div>
    </div>`;
  }).join('');
};

// Built directly from today's actual sales, grouped by whatever payment
// value each one really has -- every rupee of revenue lands in a labeled
// row here, nothing is ever lumped into a vague "Other".
const paymentIcons = { 'Cash': '💵', 'Card': '💳', 'Mobile Wallet': '📱', 'Credit (Udhaar)': '📒' };
const paymentLabels = { 'Mobile Wallet': 'EasyPaisa' };
const paymentTotals = {};
(r.salesToday || []).forEach(s => {
  const key = s.payment || 'Unspecified';
  paymentTotals[key] = (paymentTotals[key] || 0) + Number(s.grand || 0);
});
const paymentBreakdown = Object.keys(paymentTotals)
  .sort((a, b) => paymentTotals[b] - paymentTotals[a])
  .map(k => [paymentLabels[k] || k, paymentTotals[k], paymentIcons[k] || '🔹']);
const paymentColors = ['#c14a1f', '#d97706', '#0891b2', '#7c3aed', '#15803d', '#be185d', '#78716c'];
const paymentBars = paymentBreakdown.length
  ? bars(paymentBreakdown, paymentColors)
  : '<div style="color:#999;font-size:13px;">No sales today.</div>';

const orderTypeBars = bars(
  [['Walk-in', r.walkInSales, '🏪'], ['Delivery (WhatsApp)', r.deliverySales, '🛵']],
  ['#c14a1f', '#15803d']
);

// ---- all sales table (page 2) ----
const payChip = (p) => {
  const colors = { Cash: ['#166534', '#dcfce7'], Card: ['#92400e', '#fef3c7'], 'Mobile Wallet': ['#0e7490', '#cffafe'], 'Credit (Udhaar)': ['#6d28d9', '#ede9fe'] };
  const [c, bg] = colors[p] || ['#57534e', '#e7e5e4'];
  const label = p === 'Mobile Wallet' ? 'EasyPaisa' : p;
  return `<span style="background:${bg};color:${c};padding:2px 9px;border-radius:10px;font-size:11px;font-weight:700;white-space:nowrap;">${label}</span>`;
};
const typeChip = (t) => t === 'Delivery'
  ? '<span style="background:#dcfce7;color:#166534;padding:2px 9px;border-radius:10px;font-size:11px;font-weight:700;">🛵 Delivery</span>'
  : '<span style="background:#f1ede8;color:#57534e;padding:2px 9px;border-radius:10px;font-size:11px;font-weight:700;">🏪 Walk-in</span>';

const salesRows = (r.salesToday || []).length
  ? r.salesToday.map((s, i) => `<tr style="background:${i % 2 === 0 ? '#fdf6ee' : '#ffffff'};">
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;font-weight:600;color:#9a2d1f;">#${s.receiptNo}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;color:#78716c;">${s.time}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;">${s.customer}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;font-size:11.5px;color:#57534e;">${s.items || '-'}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;text-align:center;">${payChip(s.payment)}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;text-align:center;">${typeChip(s.orderType)}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #f0e0d0;text-align:right;font-weight:700;">${money(s.grand)}</td>
    </tr>`).join('')
  : '<tr><td colspan="7" style="padding:16px;color:#999;text-align:center;">No sales today.</td></tr>';

const purchaseRows = (r.purchasesToday || []).length
  ? r.purchasesToday.map(p => `<tr>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;">${p.itemName}</td>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;text-align:center;">${p.qty}</td>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;">${p.supplierName || '-'}</td>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;text-align:right;">${money(p.total)}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:10px 14px;color:#999;">No purchases logged today.</td></tr>';

const expenseRows = (r.expensesToday || []).length
  ? r.expensesToday.map(e => `<tr>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;">${e.category || '-'}</td>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;">${e.notes || '-'}</td>
      <td style="padding:8px 14px;border-bottom:1px solid #e5e5e5;text-align:right;">${money(e.amount)}</td>
    </tr>`).join('')
  : '<tr><td colspan="3" style="padding:10px 14px;color:#999;">No expenses logged today.</td></tr>';

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Daily Sales Report</title>
<style>
  @page { size: A4; margin: 0; }
  * { box-sizing: border-box; }
  body { font-family: 'Segoe UI', Arial, Helvetica, sans-serif; color: #2b2320; margin: 0; padding: 0; background: #fffaf5; }
  .page { width: 794px; min-height: 1123px; padding: 0 0 40px 0; position: relative; }
  .page-break { page-break-before: always; }
  .section-title { font-size: 15px; font-weight: 800; color: #9a2d1f; margin-bottom:8px; display:flex; align-items:center; gap:6px; }
</style>
</head>
<body>

<div class="page">
  <div style="background:linear-gradient(135deg,#7a1f14,#c14a1f 60%,#e07a3f);padding:36px 36px 30px 36px;color:#fff;position:relative;overflow:hidden;">
    <div style="position:absolute;top:-40px;right:-40px;width:180px;height:180px;border-radius:50%;background:rgba(255,255,255,0.08);"></div>
    <div style="position:absolute;bottom:-60px;right:60px;width:140px;height:140px;border-radius:50%;background:rgba(255,255,255,0.06);"></div>
    <div style="display:flex;align-items:center;gap:16px;position:relative;">
      <div style="width:56px;height:56px;border-radius:50%;background:rgba(255,255,255,0.15);border:2px solid rgba(255,255,255,0.4);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:800;flex-shrink:0;">AG</div>
      <div>
        <div style="font-size:27px;font-weight:800;letter-spacing:0.5px;">AL GHOUS BIRYANI</div>
        <div style="font-size:13px;opacity:0.85;margin-top:2px;">📄 Daily Sales Report</div>
      </div>
    </div>
    <div style="margin-top:18px;font-size:14px;background:rgba(255,255,255,0.12);display:inline-block;padding:6px 16px;border-radius:20px;position:relative;">📅 ${r.date}</div>
  </div>

  <div style="padding:26px 36px;">

    <div style="display:flex;gap:12px;margin-bottom:24px;">
      <div style="flex:1;background:#ffffff;border:1px solid #f0e0d0;border-radius:12px;padding:15px;box-shadow:0 2px 6px rgba(154,45,31,0.06);">
        <div style="font-size:10px;color:#a8a29e;text-transform:uppercase;letter-spacing:0.6px;font-weight:700;">💰 Revenue</div>
        <div style="font-size:20px;font-weight:800;color:#9a2d1f;margin-top:5px;">${money(revenue)}</div>
      </div>
      <div style="flex:1;background:#ffffff;border:1px solid #f0e0d0;border-radius:12px;padding:15px;box-shadow:0 2px 6px rgba(154,45,31,0.06);">
        <div style="font-size:10px;color:#a8a29e;text-transform:uppercase;letter-spacing:0.6px;font-weight:700;">📦 Cost of Goods</div>
        <div style="font-size:20px;font-weight:800;color:#57534e;margin-top:5px;">${money(cogs)}</div>
      </div>
      <div style="flex:1;background:linear-gradient(135deg,#ecfdf5,#f0fdf4);border:1px solid #bbf7d0;border-radius:12px;padding:15px;box-shadow:0 2px 6px rgba(21,128,61,0.08);">
        <div style="font-size:10px;color:#15803d;text-transform:uppercase;letter-spacing:0.6px;font-weight:700;">📈 Gross Profit (${marginPct}%)</div>
        <div style="font-size:20px;font-weight:800;color:#15803d;margin-top:5px;">${money(grossProfit)}</div>
      </div>
      <div style="flex:1;background:#ffffff;border:1px solid #f0e0d0;border-radius:12px;padding:15px;box-shadow:0 2px 6px rgba(154,45,31,0.06);">
        <div style="font-size:10px;color:#a8a29e;text-transform:uppercase;letter-spacing:0.6px;font-weight:700;">🧾 Avg Order</div>
        <div style="font-size:20px;font-weight:800;color:#2b2320;margin-top:5px;">${money(avgOrder)}</div>
      </div>
    </div>

    <div class="section-title">📊 Sales Breakdown <span style="font-weight:400;color:#a8a29e;font-size:12px;">· ${r.salesCount} transactions</span></div>
    <div style="display:flex;gap:20px;margin-bottom:24px;background:#fff;border:1px solid #f0e0d0;border-radius:12px;padding:18px 20px;">
      <div style="flex:1;">
        <div style="font-size:11px;font-weight:700;color:#a8a29e;text-transform:uppercase;margin-bottom:10px;">By Payment Method</div>
        ${paymentBars}
      </div>
      <div style="width:1px;background:#f0e0d0;"></div>
      <div style="flex:1;">
        <div style="font-size:11px;font-weight:700;color:#a8a29e;text-transform:uppercase;margin-bottom:10px;">By Order Type</div>
        ${orderTypeBars}
        <div style="font-size:11.5px;color:#b00020;margin-top:14px;">↩ Refunds: ${r.refundsCount} · ${money(r.refundsTotal)}</div>
      </div>
    </div>

    <div class="section-title">🏆 Top Items Today</div>
    <table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #f0e0d0;border-radius:10px;overflow:hidden;font-size:13px;margin-bottom:24px;">
      <tr style="background:#9a2d1f;color:#fff;">
        <th style="text-align:left;padding:10px 14px;font-weight:700;">Item</th>
        <th style="text-align:center;padding:10px 14px;font-weight:700;">Qty</th>
        <th style="text-align:right;padding:10px 14px;font-weight:700;">Revenue</th>
        <th style="text-align:right;padding:10px 14px;font-weight:700;">Profit</th>
      </tr>
      ${topRows}
    </table>

    <div style="display:flex;gap:14px;">
      <div style="flex:1;background:#fff;border:1px solid #f0e0d0;border-radius:10px;padding:14px 16px;">
        <div style="font-size:13px;font-weight:700;color:#b45309;margin-bottom:8px;">⚠️ Low Stock</div>
        ${badgeList(lowItems, '#92400e', '#fef3c7', 'All good — nothing low.')}
      </div>
      <div style="flex:1;background:#fff;border:1px solid #f0e0d0;border-radius:10px;padding:14px 16px;">
        <div style="font-size:13px;font-weight:700;color:#b00020;margin-bottom:8px;">⛔ Out of Stock</div>
        ${badgeList(outItems, '#991b1b', '#fee2e2', 'Nothing out of stock.')}
      </div>
    </div>
  </div>
</div>

<div class="page page-break">
  <div style="padding:32px 36px;">
    <div class="section-title">🧾 All Sales Today <span style="font-weight:400;color:#a8a29e;font-size:12px;">· ${r.salesCount} transactions</span></div>
    <table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #f0e0d0;border-radius:10px;overflow:hidden;font-size:12.5px;margin-bottom:28px;">
      <tr style="background:#9a2d1f;color:#fff;">
        <th style="text-align:left;padding:9px 12px;font-weight:700;">Receipt</th>
        <th style="text-align:left;padding:9px 12px;font-weight:700;">Time</th>
        <th style="text-align:left;padding:9px 12px;font-weight:700;">Customer</th>
        <th style="text-align:left;padding:9px 12px;font-weight:700;">Items</th>
        <th style="text-align:center;padding:9px 12px;font-weight:700;">Payment</th>
        <th style="text-align:center;padding:9px 12px;font-weight:700;">Type</th>
        <th style="text-align:right;padding:9px 12px;font-weight:700;">Total</th>
      </tr>
      ${salesRows}
    </table>

    <div style="background:#f5f5f4;border:1px solid #e5e5e5;border-radius:12px;padding:18px 20px;">
      <div style="font-size:14px;font-weight:800;color:#57534e;margin-bottom:2px;">📋 Purchases &amp; Expenses Today</div>
      <div style="font-size:11px;color:#a8a29e;margin-bottom:14px;">Reference only — not included in the profit figures on page 1.</div>

      <div style="font-size:12px;font-weight:700;color:#78716c;text-transform:uppercase;margin-bottom:6px;">Stock Purchases — ${money(r.purchasesTotal)}</div>
      <table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #e5e5e5;border-radius:8px;overflow:hidden;font-size:12px;margin-bottom:16px;">
        <tr style="background:#e7e5e4;"><th style="text-align:left;padding:7px 14px;">Item</th><th style="text-align:center;padding:7px 14px;">Qty</th><th style="text-align:left;padding:7px 14px;">Supplier</th><th style="text-align:right;padding:7px 14px;">Total</th></tr>
        ${purchaseRows}
      </table>

      <div style="font-size:12px;font-weight:700;color:#78716c;text-transform:uppercase;margin-bottom:6px;">Other Expenses — ${money(r.expensesTotal)}</div>
      <table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #e5e5e5;border-radius:8px;overflow:hidden;font-size:12px;">
        <tr style="background:#e7e5e4;"><th style="text-align:left;padding:7px 14px;">Category</th><th style="text-align:left;padding:7px 14px;">Notes</th><th style="text-align:right;padding:7px 14px;">Amount</th></tr>
        ${expenseRows}
      </table>
    </div>

    <div style="text-align:center;color:#c4b9ae;font-size:11px;margin-top:32px;border-top:1px solid #f0e0d0;padding-top:16px;">✨ Automated nightly sales report — AL GHOUS BIRYANI POS</div>
  </div>
</div>

</body></html>`;

return [{ json: { date: r.date, html } }];

const item = $input.first();
const buffer = Buffer.from(item.json.html, 'utf-8');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'daily-report.html', 'text/html');
return [{ json: item.json, binary: { htmlFile: binaryData } }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'pdf');
const base64 = buffer.toString('base64');
const date = $('Fetch daily report from Supabase').first().json.date;
return [{ json: {
  base64: base64,
  fileName: 'AL-GHOUS-BIRYANI-daily-report-' + date + '.pdf',
  caption: '📄 Daily Sales Report - ' + date
} }];

const raw = $input.first().json;
const records = (raw.messages && raw.messages.records) || [];

// TODAY's window, matching the same UTC day get_daily_report_agb reports on
// (the workflow now fires at 23:58 Asia/Karachi = 18:58 UTC the same day, so
// the whole 12pm-midnight service sits inside this window).
const now = new Date();
const dayStart = new Date(now); dayStart.setUTCHours(0,0,0,0);
const startTs = Math.floor(dayStart.getTime() / 1000);
const endTs = startTs + 86400;

const latestByKey = {};
for (const m of records) {
  const pu = m.message && m.message.pollUpdateMessage;
  const vote = pu && pu.vote;
  const pollKey = pu && pu.pollCreationMessageKey;
  if (!vote || !vote.selectedOptions || !vote.selectedOptions.length || !pollKey) continue;
  const ts = m.messageTimestamp || 0;
  if (ts < startTs || ts >= endTs) continue;
  const keyObj = m.key || {};
  const phone = (keyObj.remoteJidAlt || keyObj.remoteJid || '').split('@')[0];
  const dedupeKey = phone + '|' + pollKey.id;
  if (!latestByKey[dedupeKey] || ts > latestByKey[dedupeKey].ts) {
    latestByKey[dedupeKey] = {
      dedupeKey, ts, phone,
      customer: (m.pushName || '').trim() || 'Unknown',
      rating: vote.selectedOptions[0]
    };
  }
}

const reviews = Object.values(latestByKey).sort((a, b) => a.ts - b.ts);
return [{ json: { reviews: reviews, phones: [...new Set(reviews.map(r => r.phone))] } }];

const data = $('Build todays reviews').item.json;
const details = $input.all().map(item => item.json);
const detailsByPhone = {};
(details || []).forEach(d => { detailsByPhone[d.phone] = d; });

const reviews = data.reviews;
if (!reviews.length) {
  return [{ json: { text: '⭐ *Reviews Today*\n\nNo customer reviews received today.' } }];
}

const lines = reviews.map(r => {
  const det = detailsByPhone[r.phone] || {};
  const name = det.customer || r.customer || 'Unknown';
  const address = det.address || 'N/A';
  const when = new Date(r.ts * 1000).toLocaleTimeString();
  return `• *${name}* (${r.phone})\n  ${address}\n  ${r.rating} — ${when}`;
}).join('\n\n');

const ratingValues = { '⭐⭐⭐⭐⭐ Excellent': 5, '⭐⭐⭐ Okay': 3, '⭐ Not Great': 1 };
const withValue = reviews.filter(r => ratingValues[r.rating] != null);
const avg = withValue.length ? (withValue.reduce((s, r) => s + ratingValues[r.rating], 0) / withValue.length).toFixed(1) : null;

const header = `⭐ *Reviews Today* (${reviews.length})` + (avg ? ` — Avg: ${avg}/5` : '');
const text = header + '\n\n' + lines;

return [{ json: { text: text } }];
